130	
131	                // 판매자에게 알림 생성
132	                User seller = sale.getSeller();
133	                notificationCommandService.createNotification(
134	                        seller.getId(),
135	                        NotificationCategory.SHOPPING,
136	                        NotificationType.BID,
137	                        "상품이 성공적으로 판매 완료되었습니다. 판매 ID: " + sale.getId()
138	                );
139	
140	                log.info("판매자 알림 생성 완료: sellerId={}, saleId={}",
141	                        seller.getId(), sale.getId());
142	            } else {
143	                log.debug("Sale 상태 변경 불가 또는 Sale이 null: saleBidId={}", saleBid.getId());
