231	    /**
232	     * 배송 정보에 운송장 정보를 업데이트하고 관련 상태를 변경합니다.
233	     *
234	     * @param shipmentId 배송 ID
235	     * @param courier 택배사 이름
236	     * @param trackingNumber 운송장 번호
237	     */
238	    @Transactional
239	    public void updateTrackingInfo(Long shipmentId, String courier, String trackingNumber) {
240	        log.info("배송 운송장 정보 업데이트: shipmentId={}, courier={}, trackingNumber={}",
241	                shipmentId, courier, trackingNumber);
242	
243	        if (courier == null || courier.isBlank() || trackingNumber == null || trackingNumber.isBlank()) {
244	            log.warn("유효하지 않은 배송사 또는 운송장 번호: shipmentId={}", shipmentId);
245	            throw new ShipmentException(ShipmentErrorCode.TRACKING_INFO_REQUIRED);
246	        }
247	
248	        try {
249	            OrderShipment shipment = orderShipmentRepository.findById(shipmentId)
250	                    .orElseThrow(() -> new ShipmentException(
251	                            ShipmentErrorCode.SHIPMENT_NOT_FOUND,
252	                            "Shipment 정보를 찾을 수 없습니다: " + shipmentId
253	                    ));
254	
255	            // 운송장 정보 업데이트
256	            shipment.updateTrackingInfo(courier, trackingNumber);
257	
258	            // 배송 상태가 변경되었으므로 주문 상태도 업데이트
259	            Order order = shipment.getOrder();
260	            order.updateStatus(OrderStatus.IN_TRANSIT);
261	
262	            log.info("주문 상태 IN_TRANSIT으로 업데이트: orderId={}", order.getId());
263	
264	            // 주문한 사용자에게 알림 생성
265	            User buyer = order.getUser();
266	            notificationCommandService.createNotification(
267	                    buyer.getId(),
268	                    NotificationCategory.SHOPPING,
269	                    NotificationType.BID,
270	                    "상품이 출발하였습니다. 주문 ID: " + order.getId()
271	            );
272	
273	            log.info("구매자 출발 알림 생성: userId={}, orderId={}", buyer.getId(), order.getId());
274	
275	            // 판매 상태 업데이트 및 알림 전송
276	            updateSaleStatusToSold(order.getId());
277	
278	            // SaleBid에서 Sale 조회 및 창고 상태 업데이트
279	            SaleBid saleBid = saleBidQueryService.findByOrderId(order.getId());
280	            if (saleBid != null) {
281	                Sale sale = saleBid.getSale();
282	                if (sale != null && sale.isWarehouseStorage()) {
283	                    log.info("창고 보관 상품의 창고 상태 업데이트: saleId={}", sale.getId());
284	                    warehouseStorageCommandService.updateWarehouseStatusToSold(sale);
285	                }
286	            }
287	
288	            // OrderBid 상태를 COMPLETED로 변경
289	            updateOrderAndSaleBidStatusToCompleted(order.getId());
290	
291	            log.info("운송장 정보 업데이트 완료: shipmentId={}", shipmentId);
292	
293	        } catch (ShipmentException e) {
294	            throw e;
295	        } catch (Exception e) {
296	            log.error("운송장 정보 업데이트 실패: shipmentId={}, error={}", shipmentId, e.getMessage(), e);
297	            throw new ShipmentException(
298	                    ShipmentErrorCode.SHIPMENT_NOT_FOUND,
299	                    "운송장 정보 업데이트 중 오류 발생: " + e.getMessage(),
300	                    e
301	            );
302	        }
303	    }
